xql_query:
// ============================================================
// Rule: MS_RiskEvent Unfamiliar Features Login Detected
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with MS_RiskEvent Unfamiliar Features Login Detected.
// Severity: SEV_040_HIGH
// Category: EVASION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Tactic: TA0001 - Initial Access
// Technique: T1078 - Valid Accounts
// Tactic: TA0005 - Defense Evasion
// Technique: T1211 - Exploitation for Defense Evasion
// Tactic: TA0006 - Credential Access
// Technique: T1212 - Exploitation for Credential Access
// Technique: T1110 - Brute Force
// Tactic: TA0011 - Command and Control
// Technique: T1090.002 - Proxy: External Proxy

config case_sensitive = false
| dataset = msft_azure_raw
| alter
    timestamp = _time,
    riskDetectionId = coalesce(properties -> id, correlationid),
    userPrincipalName = properties -> userPrincipalName,
    userDisplayName = properties -> userDisplayName,
    userId = properties -> userId,
    ipAddress = properties -> ipAddress,
    city = properties -> location.city,
    state = properties -> location.state,
    countryOrRegion = properties -> location.countryOrRegion,
    geoCoordinates = properties -> location.geoCoordinates,
    appDisplayName = properties -> appDisplayName,
    riskState = properties -> riskState,
    resultType = properties -> resultType,
    resultDescription = properties -> resultDescription,
    riskEventType = properties -> riskEventType
| filter riskEventType = "unfamiliarFeatures"
| filter riskState not in ("remediated", "dismissed", "confirmedSafe")
| fields
    timestamp,
    riskDetectionId,
    userPrincipalName,
    userDisplayName,
    userId,
    ipAddress,
    city,
    state,
    countryOrRegion,
    geoCoordinates,
    appDisplayName,
    resultType,
    resultDescription,
    riskEventType
